 @Test void genuinePersistedResubmitBindingPassesSharedRecordedBoundaryUnchanged(){
  assertEquals("9b899c169063b0a7a10978c5b3619531e342cfb1de014a1c127e96370f79e3bb",ControlledKnowledgeClient.digest(GENUINE.getBytes(StandardCharsets.UTF_8)));var m=assertDoesNotThrow(()->read(GENUINE));assertEquals("PUBLICATION_RESUBMIT",((Map<?,?>)m.get("acceptanceBinding")).get("operation"));assertEquals(2L,((Number)m.get("submissionNo")).longValue());assertEquals(1L,((Number)m.get("executionNo")).longValue());assertEquals(GENUINE,wire(m));
 }
 @Test void malformedOrExtraBindingFailsClosed(){
  for(String field:List.of("operation","receiptScopeHash","requestHash","extra")){var m=ControlledKnowledgeClient.parse(GENUINE.getBytes(StandardCharsets.UTF_8),65536);var binding=new TreeMap<String,Object>((Map<String,Object>)m.get("acceptanceBinding"));binding.put(field,field.equals("operation")?null:field.equals("extra")?"unexpected":"BAD");m.put("acceptanceBinding",binding);var failure=assertThrows(ama.contract.MinutesContracts.Failure.class,()->read(wire(m)));assertEquals(ama.contract.MinutesContracts.FailureCode.PROVENANCE_UNAVAILABLE,failure.code(),field);}
 }
