 @Test void approvedLegacyVectorRemainsSupportedWithOriginalProducer(){var m=new Task11AcceptanceBindingTest().manifest();assertFalse(m.containsKey("acceptanceBinding"));String original=wire(m);var parsed=read(original);assertEquals(original,wire(parsed));assertEquals("2203b62b7bfe3cd92e512d7312b35578db040a6d720109528c7142aa645c04ce",JdbcPublicationService.spec(parsed,budget()).producerKey());}
